export const listMyNotificationsInfiniteOptions = (
  options?: Options<ListMyNotificationsData>
) =>
  infiniteQueryOptions<
    ListMyNotificationsResponse,
    DefaultError,
    InfiniteData<ListMyNotificationsResponse>,
    QueryKey<Options<ListMyNotificationsData>>,
    | number
    | Pick<
        QueryKey<Options<ListMyNotificationsData>>[0],
        'body' | 'headers' | 'path' | 'query'
      >
  >(
    // @ts-ignore
    {
      queryFn: async ({ pageParam, queryKey, signal }) => {
        // @ts-ignore
        const page: Pick<
          QueryKey<Options<ListMyNotificationsData>>[0],
          'body' | 'headers' | 'path' | 'query'
        > =
          typeof pageParam === 'object'
            ? pageParam
            : {
                query: {
                  page: pageParam
                }
              }
        const params = createInfiniteParams(queryKey, page)
        const { data } = await listMyNotifications({
          ...options,
          ...params,
          signal,
          throwOnError: true
        })
        return data
      },
      queryKey: listMyNotificationsInfiniteQueryKey(options)
    }
  )

